const C='fanroc-static-v1';self.addEventListener('install',e=>e.waitUntil(caches.open(C).then(c=>c.addAll(['./','./styles.css','./app.js','./manifest.webmanifest']))));self.addEventListener('fetch',e=>{if(e.request.method==='GET')e.respondWith(caches.match(e.request).then(r=>r||fetch(e.request).then(x=>{let z=x.clone();caches.open(C).then(c=>c.put(e.request,z));return x}).catch(()=>caches.match('./'))))});
